若数组 `a` 已按升序排列,则下面代码可以正确实现“在 `a` 中查找第一个大于等于 `x` 的元素的位置”。
```cpp
int lowerBound (vector<int>& a, int x) {
    int l=0, r=a.size();
    while(l < r) {
        int mid = (l + r) / 2;
        if(a[mid] >= x) r = mid;
        else l = mid + 1;
    }
    return l;
}
```

下面函数用“哑结点”统一处理删除单向链表中的头结点与中间结点。横线处应填()。
```cpp
struct Node{
    int val;
    Node* next;
    Node(int v): val (v), next(nullptr){}
};

Node* eraseAll (Node* head, int x) {
    Node dummy(0);
    dummy.next = head;
    Node cur = &dummy;
    while(cur->next) {
        if (cur->next->val == x) {
            Node* del = cur->next;
            // 横线处
            delete del;
        }else cur = cur->next;
    }
    return dummy.next;
}
```

