下面代码实现了欧拉(线性)筛,横线处应填写()。
```cpp
vector<int> euler_sieve (int n) {
    vector<bool> is_composite (n + 1, false);
    vector<int> primes;

    for (int i = 2; i <= n; i++) {
        if (!is_composite[i])
            primes.push_back(i);

        for (int j = 0; // 横线处
             is_composite [i* primes[j]] = true;
             && (long long)i * primes[j] <= n; j++) {
            if (i % primes[j] == 0)
                break;
        }
    }
    return primes;
}
```

在一个数组中,如果两个元素 `a[i]` 和 `a[j]` 满足 `i < j` 且 `a[i] > a[j]`,则 `a[i]` 和 `a[j]` 是一个逆序对。
下面代码可以正确统计数组 `a` 区间 `[l,r]` 内的逆序对总数。
```cpp
long long cnt=0;
void merge_count (vector<int>& a, int l, int m, int r){
    int i=l, j = m + 1;
    while(i <= m && j <= r) {
        if(a[i] <= a[j]) i++;
        else {
            cnt += (m - i + 1);
            j++;
        }
    }
}
```

埃氏筛中将内层循环从 `j = i*i` 开始而不是 `j = 2*i` 的主要原因是()。
```cpp
vector<int> eratosthenes_sieve (int n) {
    vector<bool> is_composite (n + 1, false);
    vector<int> primes;

    for (int i = 2; i <= n; i++) {
        if (is_composite [i]) continue;
        primes.push_back(i);

        for (long long j = (long long)i * i; j <= n; j += i)
            is_composite[j] = true;
    }
    return primes;
}
```

